// snippets from the Sass documentation at http://sass-lang.com/

/* css stuff */
/* charset */
@charset "UTF-8";

/* nested rules */
#main {
  width: 97%;
  p, div {
    font-size: 2em;
    a { font-weight: bold; }
  }
  pre { font-size: 3em; }
}

/* parent selector (&) */
#main {
  color: black;
  a {
    font-weight: bold;
    &:hover { color: red; }
  }
}
